#include <iostream>
#include <unordered_map>
#include <string>
int main() {
    std::unordered_map<std::string, int> f;
    for (std::string w : {"apple", "banana", "apple", "cherry", "banana", "apple"})
        f[w]++;
    std::cout << "apple=" << f["apple"] << '\n';
    std::cout << "banana=" << f["banana"] << '\n';
    std::cout << "size=" << f.size() << '\n';
}
